//! End-to-end tests against the public fixture generated by
//! examples/sample_screenplay.rs. Unlike tests/real_world.rs, these always run.

mod common;

#[allow(dead_code)]
#[path = "../examples/sample_screenplay.rs"]
mod generator;

use std::fs;

use scriplite::batch::{GenerateOptions, generate};
use scriplite::model::{DialogueLane, GenerationManifest};
use scriplite::{AppError, Color, analyze_pdf};
use sha2::{Digest, Sha256};

use common::{bind_engine, count_highlight_rectangles, fixture, lock};

const SAMPLE: &str = "public/sample-screenplay.pdf";
const DEFAULT_FILL: &str = "0.996078 0.996078 0.498039 rg";

/// (name, cue blocks, dual blocks, highlighted visual lines), in script order.
const EXPECTED: [(&str, usize, usize, usize); 3] = [
    ("DEV", 6, 1, 25),
    ("MARA", 5, 1, 17),
    ("CONDUCTOR", 1, 0, 3),
];

#[test]
fn committed_fixture_matches_generator() {
    let committed = fs::read(fixture(SAMPLE)).unwrap();
    assert!(
        committed == generator::build_pdf(),
        "{SAMPLE} is stale; run `cargo run --example sample_screenplay`"
    );
}

#[test]
fn sample_detection_matches_expected_counts() {
    let _guard = lock();
    let Some(engine) = bind_engine() else {
        return;
    };
    let analysis = analyze_pdf(&engine, &fixture(SAMPLE)).unwrap();
    assert!(analysis.report.valid, "{:?}", analysis.report.diagnostics);
    assert!(analysis.report.diagnostics.is_empty());
    assert_eq!(analysis.report.source.page_count, 3);
    let actual = analysis
        .report
        .characters
        .iter()
        .map(|character| {
            (
                character.name.as_str(),
                character.cue_blocks,
                character.dual_blocks,
                character.highlighted_visual_lines,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(actual, EXPECTED);

    // The dual-dialogue pair stays in its own column.
    let half = analysis.report.source.width_points / 2.0;
    for block in &analysis.blocks {
        match block.lane {
            DialogueLane::DualLeft => assert!(block.runs.iter().all(|run| run.bounds.x1 < half)),
            DialogueLane::DualRight => assert!(block.runs.iter().all(|run| run.bounds.x0 > half)),
            DialogueLane::Main => {}
        }
    }

    // The page-1 speech continues after (MORE) as DEV (CONT'D) on page 2.
    let continued = analysis
        .blocks
        .iter()
        .find(|block| block.cue_text == "DEV (CONT'D)")
        .unwrap();
    assert_eq!(continued.character_key, "DEV");
    assert_eq!(continued.page, 2);
    assert!(
        analysis
            .blocks
            .iter()
            .any(|block| block.page == 1 && block.runs.iter().any(|run| run.text == "(MORE)"))
    );
}

#[test]
fn sample_generates_every_speaker_with_text_preserved() {
    let _guard = lock();
    let Some(engine) = bind_engine() else {
        return;
    };
    let temporary = tempfile::tempdir().unwrap();
    let output_dir = temporary.path().join("batch");
    let options = GenerateOptions {
        input: fixture(SAMPLE),
        output_dir: output_dir.clone(),
        characters: Vec::new(),
        color: Color::default(),
        force: false,
    };
    let manifest = generate(&engine, &options).unwrap();
    let files = &manifest.generation.files;
    assert_eq!(files.len(), EXPECTED.len());

    let source = engine.extract(&fixture(SAMPLE)).unwrap();
    for (file, (_, _, _, lines)) in files.iter().zip(EXPECTED) {
        let path = output_dir.join(&file.filename);
        assert_eq!(count_highlight_rectangles(&path, DEFAULT_FILL), lines);
        let bytes = fs::read(&path).unwrap();
        assert_eq!(file.sha256, format!("{:x}", Sha256::digest(&bytes)));
        let generated = engine.extract(&path).unwrap();
        let text = |document: &scriplite::model::ExtractedDocument| {
            document
                .pages
                .iter()
                .map(|page| page.extracted_text.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(text(&generated), text(&source));
    }

    let written: GenerationManifest = serde_json::from_slice(
        &fs::read(output_dir.join("sample-screenplay.manifest.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(written.generation.files.len(), EXPECTED.len());

    let collision = generate(&engine, &options).unwrap_err();
    assert!(matches!(collision, AppError::Collision(_)));
}

#[test]
fn sample_generates_one_speaker_in_a_custom_color() {
    let _guard = lock();
    let Some(engine) = bind_engine() else {
        return;
    };
    let temporary = tempfile::tempdir().unwrap();
    let output_dir = temporary.path().join("batch");
    let options = GenerateOptions {
        input: fixture(SAMPLE),
        output_dir: output_dir.clone(),
        characters: vec!["mara".to_string()],
        color: "#3366CC".parse().unwrap(),
        force: false,
    };
    let manifest = generate(&engine, &options).unwrap();
    assert_eq!(manifest.generation.files.len(), 1);
    let output = output_dir.join("sample-screenplay (Mara).pdf");
    assert_eq!(
        count_highlight_rectangles(&output, "0.200000 0.400000 0.800000 rg"),
        17
    );

    let unknown = GenerateOptions {
        characters: vec!["Nobody".to_string()],
        force: true,
        ..options
    };
    assert!(matches!(
        generate(&engine, &unknown),
        Err(AppError::UnknownCharacter(_))
    ));
}
